import React, { useRef, useState, useEffect } from 'react';
import './Product.css';
import Img1 from "../assets/images/LD-250W.png";
import Img2 from "../assets/images/LD-250W_RF.png";
import Img3 from "../assets/images/LD-250W_BST.png";
import Img4 from "../assets/images/LD-RGB_BST.png";
import Img5 from "../assets/images/LD-RGB.png";
import Img6 from "../assets/images/img6.jpeg";

const Products = () => {
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [selectedProduct, setSelectedProduct] = useState(null);
  const sectionRef = useRef(null);
  const [isVisible, setIsVisible] = useState(false);


useEffect(() => {
  const observer = new IntersectionObserver(
    ([entry]) => {
      if (entry.isIntersecting) {
        setIsVisible(true);
        observer.disconnect();
      }
    },
    { threshold: 0.3 } // Trigger when 30% of section is visible
  );

  if (sectionRef.current) {
    observer.observe(sectionRef.current);
  }

  return () => observer.disconnect();
}, []);

  // Data structure for categories and products
  const categories = [
    {
      name: "MASTER SMART HOME",
      image: Img1,
      products: [
        { name: "ILLUMINATION", description: "Smart lighting control (Wi-Fi)", image: Img1 },
        { name: "SHADING SYSTEMS", description: "Smart awnings and shutters (Wi-Fi)", image: Img2 },
        { name: "APPLIANCES CONTROL", description: "Smart appliance control (Wi-Fi)", image: Img3 },
        { name: "HEATING / COOLING", description: "Smart heating and cooling (Wi-Fi)", image: Img4 },
        { name: "VISUALIZATION", description: "Smart control and management (Wi-Fi)", image: Img5 }
      ]
    },
    {
      name: "LED CONTROLLERS",
      image: Img2,
      products: [
        { name: "LD-250W", description: "Led Controller LD-250W was designed to fulfill the needs of illumination control and management of lighting fixtures using LED technology at 12VDC and 24VDC like Led Stripes, Led bulbs, etc. It is a safe and reliable product because it was designed with special integrated circuits and plastic parts for adverse operating conditions.", image: Img1 },
        { name: "LD-250W-RF", description: "Led Controller LD-250W-RF was designed to fulfill the needs of illumination control and management of lighting fixtures using LED technology at 12VDC and 24VDC like Led Stripes, Led bulbs, etc. It is a safe and reliable product because it was designed with special integrated circuits and plastic parts for adverse operating conditions.", image: Img2 },
        { name: "LD-250W-BST", description: "Led Controller LD-250W-BST (Booster-Amplifier one channel) was designed to fulfill the needs of illumination control and management of lighting fixtures using LED technology at 12VDC and 24VDC like Led Stripes, Led bulbs, etc. It is a safe and reliable product because it was designed with special integrated circuits and plastic parts for adverse operating conditions.", image: Img3 },
        { name: "LD-RGB-BST", description: "Led Controller LD-RGB-BST (Booster-Amplifier three channels) was designed to fulfill the needs of illumination control and management of lighting fixtures using LED technology at 12VDC and 24VDC like Led Stripes, Led bulbs, etc. It is a safe and reliable product because it was designed with special integrated circuits and plastic parts for adverse operating conditions.", image: Img4 },
        { name: "LD-RGB", description: "Led Controller LD-RGB was designed to fulfill the needs of illumination control and management of lighting fixtures using LED technology at 12VDC and 24VDC like Led Stripes and R-G-B projectors. It is a safe and reliable product because it was designed with special integrated circuits and plastic parts for adverse operating conditions.", image: Img5 }
      ]
    },
    {
      name: "WALL – MOUNTING DIMMER",
      image: Img3,
      products: [
        { name: "DM-400L/N", description: "Wall Mounting Dimmer Multi 1000W", image: Img5 },
        { name: "DM-1000W", description: "Allerretour", image: Img6 }
      ]
    },
    {
      name: "FLUSH – MOUNTING DIMMER",
      image: Img4,
      products: [
        { name: "DM-400B", description: "Flush Mounted Dimmer 400W (Control with Button)", image: Img1 },
        { name: "DM-400B-RF", description: "Flush Mounted Dimmer 400W (Button & RF)", image: Img2 }
      ]
    },
    {
      name: "RAIL – MOUNTING DIGITAL DIMMER",
      image: Img5,
      products: [
        { name: "DM-300/b", description: "Rail Mounting Dimmer 300W LED (Remote Control)", image: Img3 },
        { name: "DM-DGL/b", description: "Rail Mounting Digital Dimmer 1000W", image: Img4 }
      ]
    },
    {
      name: "SURFACE – MOUNTING DIMMER",
      image: Img6,
      products: [
        { name: "DM-2500W", description: "Dimmer Professional Multi-LED 2500W", image: Img5 },
        { name: "DM-2500", description: "Dimmer Professional Multi-LED 2500W", image: Img6 },
        { name: "DM-PRO 1-10V", description: "Dimmer Professional 1-10V", image: Img1 }
      ]
    }
    // Add more categories and products here
  ];

  // Handle back to category view
  const goBack = () => {
    setSelectedCategory(null);
    setSelectedProduct(null);
  };

  return (
    <section ref={sectionRef} className={`products-section fade-in-section ${isVisible ? 'visible' : ''}`}>
    <div className="container">
    <div className="products-section">
      <div className="container">

        {/* ======= CATEGORY VIEW ======= */}
        {!selectedCategory && (
          <>
            <h2 className="products-title">Our Products</h2>
            <div className="category-grid">
              {categories.map((category, index) => (
                <div key={index} className="category-card">
                  <img src={category.image} alt={category.name} />
                  <h3>{category.name}</h3>
                  <button onClick={() => setSelectedCategory(category)}>View Products</button>
                </div>
              ))}
            </div>
          </>
        )}

        {/* ======= PRODUCT VIEW ======= */}
        {selectedCategory && (
          <>
            <button className="back-button" onClick={goBack}>
  <span className="back-circle">
    ◀
  </span>
  Back to Products
</button>
            <h2 className="products-title">{selectedCategory.name}</h2>
            <div className="products-grid">
              {selectedCategory.products.map((product, index) => (
                <div
                  key={index}
                  className="product-card"
                  onClick={() => setSelectedProduct(product)}
                >
                  <img src={product.image} alt={product.name} />
                  <h4>{product.name}</h4>
                </div>
              ))}
            </div>
          </>
        )}

        {/* ======= PRODUCT MODAL ======= */}
        {selectedProduct && (
          <div className="product-modal">
            <div className="modal-content">
              <button className="close-button" onClick={() => setSelectedProduct(null)}>×</button>
              <img src={selectedProduct.image} alt={selectedProduct.name} />
              <h2>{selectedProduct.name}</h2>
              <p>{selectedProduct.description}</p>
            </div>
          </div>
        )}
      </div>
    </div>
    </div>
  </section>  
  );
};

export default Products;
